export async function listPendingInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const rows = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        gt(invitations.expiresAt, toIsoTimestamp(new Date())),
      ),
    )
    .orderBy(desc(invitations.createdAt))
    .all();

  return rows.map(toInvitation);
}

/**
 * Unscoped-by-pending lookup, used by resend (which must find an invitation
 * that has already expired) and by the accept flow's error messages.
 */
export async function findInvitationById(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

/**
 * Case-insensitive lookup of a still-pending (not accepted, not revoked, not
 * expired) invitation for an address, used to refuse duplicate invites.
 */
export async function findPendingInvitationByEmail(
  orgId: OrgId,
  email: string,
): Promise<Invitation | null> {
  const rows = await listPendingInvitations(orgId);
  const needle = email.toLowerCase();
  return rows.find((row) => row.email.toLowerCase() === needle) ?? null;
}

